<?php
require __DIR__.'/auth.php';require __DIR__.'/../event-common.php';
$editId=filter_input(INPUT_GET,'edit',FILTER_VALIDATE_INT) ?: 0;
$edit=null;
if($editId){$s=$conn->prepare('SELECT * FROM events WHERE event_id=?');$s->bind_param('i',$editId);$s->execute();$edit=$s->get_result()->fetch_assoc();$s->close();}
$events=$conn->query("SELECT e.*, (SELECT COUNT(*) FROM event_registrations r WHERE r.event_id=e.event_id AND r.status IN ('registered','attended')) AS participants, (SELECT COUNT(*) FROM event_artworks ea WHERE ea.event_id=e.event_id) AS artwork_count FROM events e ORDER BY e.starts_at DESC,e.event_id DESC")->fetch_all(MYSQLI_ASSOC);
$regEvent=filter_input(INPUT_GET,'registrations',FILTER_VALIDATE_INT) ?: 0;
$registrations=[];
if($regEvent){$s=$conn->prepare('SELECT r.registration_id,r.status,r.registered_at,u.FULL_NAME,u.EMAIL FROM event_registrations r JOIN users u ON u.USER_ID=r.user_id WHERE r.event_id=? ORDER BY r.registered_at DESC');$s->bind_param('i',$regEvent);$s->execute();$registrations=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();}
$msg=['saved'=>'Exhibition saved.','status'=>'Exhibition status updated.','attendance'=>'Attendance updated.','invalid'=>'Please check your input and try again.','error'=>'Unable to save; check database setup.'][($_GET['msg']??'')]??'';
function eventInputDate($value){return $value ? date('Y-m-d\TH:i',strtotime($value)) : '';}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Exhibitions | MIRA Admin</title><script>try{document.documentElement.dataset.theme=localStorage.getItem('mira-theme')==='dark'?'dark':'light'}catch(e){}</script><link rel="stylesheet" href="admin.css"><link rel="stylesheet" href="../event.css"><script src="admin.js" defer></script><link rel="stylesheet" href="../mira-design-system.css?v=1">
<link rel="stylesheet" href="mira-admin-polish.css?v=1">
</head><body class="admin-page"><div class="admin-layout"><?php $activeAdminPage="events"; require __DIR__.'/sidebar.php'; ?><main class="admin-main"><header class="admin-topbar"><p class="admin-breadcrumb">MIRA / <strong>Exhibitions</strong></p><button id="themeToggle" class="admin-theme-toggle" type="button">☾ Dark mode</button></header><div class="event-container"><p class="event-eyebrow">MIRA · ADMIN STUDIO</p><h1>Exhibitions & showcases ✦</h1><p class="event-muted">Create events, select approved artwork, and review participation.</p><?php if($msg):?><p class="event-alert" role="status"><?=eventEsc($msg)?></p><?php endif;?>
<div class="event-columns"><section class="event-card"><h2><?= $edit?'Edit exhibition':'Create an exhibition' ?></h2><form method="post" action="save-event.php" enctype="multipart/form-data" class="event-form"><input type="hidden" name="csrf" value="<?=eventEsc(eventToken())?>"><input type="hidden" name="event_id" value="<?= (int)($edit['event_id']??0) ?>"><label>Title<input name="title" maxlength="200" required value="<?=eventEsc($edit['title']??'')?>"></label><label>Description<textarea name="description" rows="4" maxlength="5000"><?=eventEsc($edit['description']??'')?></textarea></label><label>Exhibition poster (JPG, PNG, WebP; max 3MB)<input type="file" name="poster" accept="image/jpeg,image/png,image/webp"></label><?php if(!empty($edit['poster_path'])):?><img class="event-poster-preview" src="../<?=eventEsc($edit['poster_path'])?>" alt="Existing exhibition poster"><?php endif;?><label>Venue<input name="venue" maxlength="200" required value="<?=eventEsc($edit['venue']??'')?>"></label><div class="event-duo"><label>Starts<input type="datetime-local" name="starts_at" required value="<?=eventEsc(eventInputDate($edit['starts_at']??null))?>"></label><label>Ends<input type="datetime-local" name="ends_at" required value="<?=eventEsc(eventInputDate($edit['ends_at']??null))?>"></label></div><label>Registration deadline<input type="datetime-local" name="registration_deadline" required value="<?=eventEsc(eventInputDate($edit['registration_deadline']??null))?>"></label><label>Maximum participants<input type="number" min="1" max="100000" name="capacity" required value="<?= (int)($edit['capacity']??100) ?>"></label><label>Status<select name="status"><?php foreach(['draft','published','cancelled','completed'] as $st):?><option value="<?=$st?>" <?=($edit['status']??'draft')===$st?'selected':''?>><?=ucfirst($st)?></option><?php endforeach;?></select></label><button class="event-primary" type="submit">Save exhibition</button><?php if($edit):?><a href="events.php">Cancel editing</a><?php endif;?></form></section>
<section class="event-card"><h2>Scheduled exhibitions</h2><?php if(!$events):?><p class="event-muted">No exhibitions created yet.</p><?php endif;?><?php foreach($events as $e):?><article class="event-list-item"><?php if(!empty($e['poster_path'])):?><img class="event-list-poster" src="../<?=eventEsc($e['poster_path'])?>" alt="Exhibition poster"><?php endif;?><div class="event-flex"><h3><?=eventEsc($e['title'])?></h3><span class="event-status"><?=eventEsc(ucfirst($e['status']))?></span></div><p class="event-muted"><?=eventEsc($e['venue'])?> · <?=eventEsc(date('M j, Y g:i A',strtotime($e['starts_at'])))?></p><p><?= (int)$e['participants'] ?> / <?= (int)$e['capacity'] ?> participants · <?= (int)$e['artwork_count'] ?> selected artworks</p><div class="event-actions"><a href="event-requests.php?event_id=<?=(int)$e['event_id']?>">Artwork requests</a><a href="events.php?edit=<?=(int)$e['event_id']?>">Edit</a><a href="event-artworks.php?event_id=<?=(int)$e['event_id']?>">Select artworks</a><a href="events.php?registrations=<?=(int)$e['event_id']?>">Registrations</a></div></article><?php endforeach;?></section></div>
<?php if($regEvent):?><section class="event-card event-space"><h2>Registrations for event #<?= (int)$regEvent ?></h2><div class="event-tablewrap"><table class="event-table"><thead><tr><th>Student</th><th>Email</th><th>Status</th><th>Attendance</th></tr></thead><tbody><?php foreach($registrations as $r):?><tr><td><?=eventEsc($r['FULL_NAME'])?></td><td><?=eventEsc($r['EMAIL'])?></td><td><?=eventEsc($r['status'])?></td><td><?php if($r['status']!=='cancelled'):?><form method="post" action="save-event.php"><input type="hidden" name="csrf" value="<?=eventEsc(eventToken())?>"><input type="hidden" name="action" value="attendance"><input type="hidden" name="registration_id" value="<?= (int)$r['registration_id'] ?>"><input type="hidden" name="event_id" value="<?= (int)$regEvent ?>"><select name="attendance"><option value="registered" <?=$r['status']==='registered'?'selected':''?>>Registered</option><option value="attended" <?=$r['status']==='attended'?'selected':''?>>Attended</option></select><button type="submit">Update</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php if(!$registrations):?><p>No registrations yet.</p><?php endif;?></section><?php endif;?></div></main></div></body></html>
